function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const n = size === 'large' ? pick(900, 1000) : pick(2, 8);
  if (size !== 'large' && rand() < 0.4) {
    const top = pick(2, 9);
    return [Array.from({ length: n }, () => pick(1, top))];
  }
  // Start from a strictly increasing array of distinct values, then disturb 0 to 2 positions.
  const nums = [];
  for (let value = 1; value <= 1000 && nums.length < n; value++) {
    if (rand() * (1001 - value) < n - nums.length) nums.push(value);
  }
  const changes = pick(0, 2);
  for (let c = 0; c < changes; c++) {
    const index = pick(0, n - 1);
    const near = nums[index] + pick(-3, 3);
    nums[index] = rand() < 0.5 ? Math.min(1000, Math.max(1, near)) : pick(1, 1000);
  }
  return [nums];
}
